css:
.loader {
  position: relative;
  width: 44px;
  height: 52px;
  perspective: 140px;
}
.loader::before {
  content: "";
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 50%;
  background: #4338ca;
  border-radius: 0 0 6px 6px;
}
.loader::after {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 50%;
  background: #6366f1;
  border-radius: 6px 6px 0 0;
  box-shadow: inset 0 -1px 0 #312e81;
}
.loader i {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 50%;
  background: #6366f1;
  border-radius: 6px 6px 0 0;
  transform-origin: bottom center;
  backface-visibility: hidden;
  animation: flip 1.4s ease-in infinite;
}
@keyframes flip {
  0% { transform: rotateX(0deg); }
  50%, 100% { transform: rotateX(-90deg); }
}
